
let googleMapsPromise=null;async function loadGoogleMaps(){if(window.google?.maps)return window.google.maps;if(googleMapsPromise)return googleMapsPromise;googleMapsPromise=(async()=>{const cfg=await api('/api/maps-config');await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://maps.googleapis.com/maps/api/js?key='+encodeURIComponent(cfg.apiKey)+'&v=weekly&libraries=places';script.async=true;script.onload=resolve;script.onerror=()=>reject(new Error('Não foi possível carregar o Google Maps.'));document.head.appendChild(script)});return window.google.maps})();return googleMapsPromise}
function splitRouteNotes(notes){return String(notes||'').split(/\n|\s*[•·]\s*/).map(x=>x.trim()).filter(Boolean)}
function cleanStopText(text){return String(text||'').replace(/^\d{1,2}:\d{2}\s*[-–—:]?\s*/,'').replace(/^(depois|em seguida|então)\s*[-–—:]?\s*/i,'').trim()}
function stopCandidate(text){const x=cleanStopText(text);if(!x)return null;const vague=/\b(um|uma)\s+(miradouro|restaurante|café|cafe|bar|praia|parque|museu)\b/i.exec(x);if(vague)return {label:x,query:vague[2],ambiguous:true};const beforeColon=x.split(':')[0].trim();const narrative=/^(chegada|comece|vá |va |aproveite|termine|terminando|almoço|almoco|jantar|retorno|volta|você |voce )/i.test(x);if(narrative&&!x.includes(':'))return null;const q=(x.includes(':')?beforeColon:x).replace(/^(subida ao|visita ao|visita à|passeio pelo|passeio pela)\s+/i,'').trim();if(q.length<3||q.length>90)return null;return {label:q,query:q,ambiguous:false}}
function itineraryDays(){const groups=new Map();for(const item of currentTrip.itinerary){const date=item.item_date||'sem-data';if(!groups.has(date))groups.set(date,[]);groups.get(date).push(item)}return [...groups.entries()].sort((a,b)=>a[0].localeCompare(b[0]))}
const routePlaceCache=new Map();async function resolveDayStops(items,trip){await loadGoogleMaps();const {Place}=await google.maps.importLibrary('places');const jobs=[];for(const item of items){const context=[item.location,item.title,trip.destinations].filter(Boolean).join(', ');const raw=splitRouteNotes(item.notes);const candidates=raw.map(stopCandidate).filter(Boolean);if(item.location&&!candidates.some(c=>c.query.toLowerCase()===String(item.location).toLowerCase()))candidates.unshift({label:item.location,query:item.location,ambiguous:false});for(const c of candidates.slice(0,24))jobs.push({c,context})}const lookup=async({c,context})=>{const key=`${c.ambiguous?'a':'e'}|${c.query}|${context}`.toLocaleLowerCase('pt-BR');if(routePlaceCache.has(key))return routePlaceCache.get(key);const promise=(async()=>{try{const r=await Place.searchByText({textQuery:`${c.query}, ${context}`,fields:['id','displayName','formattedAddress','location'],maxResultCount:c.ambiguous?5:1,language:'pt-BR'});const found=r.places||[];if(!found.length)return {unresolved:c.label};if(c.ambiguous&&found.length>1)return {stop:{ambiguous:true,label:c.label,choices:found.map(x=>({label:x.displayName||c.query,address:x.formattedAddress||'',location:x.location}))}};const x=found[0];return {stop:{label:x.displayName||c.label,address:x.formattedAddress||`${c.query}, ${context}`,location:x.location}}}catch(e){console.warn('Places route lookup',c.query,e);return {unresolved:c.label}}})();routePlaceCache.set(key,promise);return promise};const results=[];for(let i=0;i<jobs.length;i+=6)results.push(...await Promise.all(jobs.slice(i,i+6).map(lookup)));return {stops:results.filter(x=>x.stop).map(x=>x.stop),unresolved:results.filter(x=>x.unresolved).map(x=>x.unresolved)}}
async function drawDayMarkers(stops){const map=window.ihTripMap;if(!map)return;window.ihDayMarkers?.forEach(m=>m.setMap(null));window.ihDayMarkers=[];const bounds=new google.maps.LatLngBounds();let n=0;for(const s of stops){if(s.ambiguous||!s.location)continue;n++;const marker=new google.maps.Marker({map,position:s.location,title:`${n}. ${s.label}`,label:{text:String(n)}});window.ihDayMarkers.push(marker);bounds.extend(s.location)}if(n===1){map.setCenter(bounds.getCenter());map.setZoom(15)}else if(n>1)map.fitBounds(bounds,60)}
async function initTripGoogleMap(rows,trip){await loadGoogleMaps();const mapEl=$('#tripGoogleMap');if(!mapEl)return;const map=new google.maps.Map(mapEl,{center:{lat:20,lng:0},zoom:2,mapTypeControl:false,streetViewControl:false,fullscreenControl:true});window.ihTripMap=map;if(window.ihRouteLine){window.ihRouteLine.setMap(null);window.ihRouteLine=null;}window.ihDayMarkers=[]}

function decodeGooglePolyline(encoded){let index=0,lat=0,lng=0,out=[];while(index<encoded.length){let b,shift=0,result=0;do{b=encoded.charCodeAt(index++)-63;result|=(b&31)<<shift;shift+=5}while(b>=32);lat+=(result&1)?~(result>>1):(result>>1);shift=0;result=0;do{b=encoded.charCodeAt(index++)-63;result|=(b&31)<<shift;shift+=5}while(b>=32);lng+=(result&1)?~(result>>1):(result>>1);out.push({lat:lat/1e5,lng:lng/1e5})}return out}
async function drawGoogleRoute(r){await loadGoogleMaps();const map=window.ihTripMap;if(!map||!r.polyline)return;if(window.ihRouteLine)window.ihRouteLine.setMap(null);const path=decodeGooglePolyline(r.polyline);window.ihRouteLine=new google.maps.Polyline({path,map,strokeOpacity:.85,strokeWeight:5});const bounds=new google.maps.LatLngBounds();path.forEach(p=>bounds.extend(p));if(path.length)map.fitBounds(bounds,50)}
function formatRouteDuration(mins){if(mins<60)return `${mins} min`;const h=Math.floor(mins/60),m=mins%60;return `${h} h${m?` ${m} min`:''}`}
let me=null,authMode='login',currentTrip=null,currentTab='overview';const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));async function api(url,opt={}){const r=await fetch(url,{headers:{'content-type':'application/json',...(opt.headers||{})},...opt});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||'Erro na solicitação');return d}const money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(v||0),fmt=(v,d=2)=>Number(v||0).toLocaleString('pt-BR',{maximumFractionDigits:d});function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function show(id){$$('.page').forEach(x=>x.classList.add('hidden'));$('#'+id).classList.remove('hidden');if(id==='dashboard'&&me)loadDashboard();if(id==='admin'&&me?.role==='admin')loadAdmin()}$$('[data-go]').forEach(b=>b.onclick=()=>{const p=b.dataset.go;if((p==='dashboard'||p==='admin')&&!me)return openAuth();show(p)});function syncNav(){$$('.private').forEach(x=>x.classList.toggle('hidden',!me));$$('.admin').forEach(x=>x.classList.toggle('hidden',me?.role!=='admin'));$('#loginBtn').classList.toggle('hidden',!!me);$('#logoutBtn').classList.toggle('hidden',!me);$$('.travelerNav').forEach(x=>x.classList.toggle('hidden',me?.role==='admin'));if($('#newTrip'))$('#newTrip').classList.toggle('hidden',me?.role==='admin')}async function init(){try{me=await api('/api/me')}catch{me=null}syncNav();$('#pDate').value=new Date().toISOString().slice(0,10);loadRadar('EUR');loadRadar('USD');loadVetInfo()}function openAuth(mode='login'){authMode=mode;$('#authTitle').textContent=mode==='login'?'Entrar na minha conta':'Criar minha conta';$('#nameWrap').classList.toggle('hidden',mode==='login');$('#authSubmit').textContent=mode==='login'?'Entrar':'Criar conta';$('#authLoginTab').classList.toggle('active',mode==='login');$('#authRegisterTab').classList.toggle('active',mode==='register');$('#authMsg').textContent='';if(!$('#authDialog').open)$('#authDialog').showModal()}$('#loginBtn').onclick=()=>openAuth('login');$('#startBtn').onclick=()=>openAuth('register');$('#authLoginTab').onclick=()=>openAuth('login');$('#authRegisterTab').onclick=()=>openAuth('register');$('#authSubmit').onclick=async()=>{try{await api('/api/auth/'+authMode,{method:'POST',body:JSON.stringify({email:$('#authEmail').value,password:$('#authPassword').value,name:$('#authName').value})});me=await api('/api/me');syncNav();$('#authDialog').close();show(me.role==='admin'?'admin':'dashboard')}catch(e){$('#authMsg').textContent=e.message}};$('#logoutBtn').onclick=async()=>{await api('/api/auth/logout',{method:'POST'});me=null;syncNav();show('home')};$('#newTrip').onclick=()=>{const f=$('#tripForm');f.reset();$('#tDest').value='';$('#countrySummary').textContent='Selecione um ou mais países';$('#countryOptions').dataset.ready='';$('#tripMsg').textContent='';setupCountryPicker();$('#tTravelers').value=1;renderCompanionFields();$('#tTarget').value=0;$('#tripDialog').showModal()};$('#tripForm').onsubmit=async e=>{e.preventDefault();if(!$('#tDest').value.trim()){ $('#tripMsg').textContent='Selecione pelo menos um destino.'; $('#countryPicker').open=true; return } try{await api('/api/trips',{method:'POST',body:JSON.stringify({name:$('#tName').value,destinations:$('#tDest').value,start_date:$('#tStart').value,end_date:$('#tEnd').value,travelers:$('#tTravelers').value,profile:$('#tProfile').value,currency:$('#tCurrency').value,target_amount:$('#tTarget').value,companions:$$('.companionName').map(x=>x.value.trim())})});e.target.reset();$('#tDest').value='';$('#countrySummary').textContent='Selecione um ou mais países';$('#countryOptions').dataset.ready='';setupCountryPicker();$('#tTravelers').value=1;renderCompanionFields();$('#tTarget').value=0;$('#tripDialog').close();loadDashboard()}catch(err){$('#tripMsg').textContent=err.message}};
async function loadDashboard(){if(me?.role==='admin'){show('admin');return}const [trips,purchases,alerts]=await Promise.all([api('/api/trips'),api('/api/purchases'),api('/api/alerts')]);$('#hello').textContent=`Olá, ${me.name.split(' ')[0]}!`;$('#tripCount').textContent=trips.length;$('#brlTotal').textContent=money(purchases.reduce((a,p)=>a+p.total_brl,0));const sums={};purchases.forEach(p=>sums[p.currency]=(sums[p.currency]||0)+p.amount);$('#currencyTotal').textContent=Object.entries(sums).map(([c,v])=>`${fmt(v)} ${c}`).join(' · ')||'—';$('#purchaseTrip').innerHTML=trips.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('');$('#purchaseTrip').disabled=!trips.length;if(trips.length)$('#purchaseTrip').value=trips[0].id;$('#trips').innerHTML=trips.length?trips.map(t=>{const bought=purchases.filter(p=>p.trip_id===t.id&&p.currency===t.currency).reduce((a,p)=>a+p.amount,0),pct=t.target_amount?Math.min(100,bought/t.target_amount*100):0,days=t.start_date?Math.ceil((new Date(t.start_date+'T12:00:00')-new Date())/86400000):null;return `<article class="tripCard" onclick="openTrip(${t.id})"><div class="tripTop"><div><span class="eyebrow">${days!==null?(days>=0?`Faltam ${days} dias`:'Viagem realizada'):'Data a definir'}</span><h3>${esc(t.name)}</h3><p>${esc(t.destinations)||'Destinos a definir'}</p></div><button class="danger" onclick="event.stopPropagation();delTrip(${t.id})">Excluir</button></div><div class="progress"><i style="width:${pct}%"></i></div><div class="tripMeta"><b>${fmt(bought)} / ${fmt(t.target_amount)} ${t.currency}</b><span>${pct.toFixed(0)}% da meta</span></div><button type="button" class="linkBtn" onclick="event.stopPropagation();openTrip(${t.id})">Abrir planejamento →</button></article>`}).join(''):'<div class="empty">Você ainda não cadastrou nenhuma viagem.</div>';$('#purchases').innerHTML=purchases.slice(0,6).map(p=>`<div class="listItem"><b>${fmt(p.amount)} ${p.currency}</b><span>${money(p.total_brl)} · VET ${p.vet.toFixed(4)} · ${brDate(p.purchased_at)}</span></div>`).join('')||'<div class="empty">Nenhuma compra registrada.</div>';$('#alerts').innerHTML=alerts.map(a=>`<div class="listItem"><b>${a.currency} ${a.kind==='below'?'abaixo':'acima'} de R$ ${a.threshold.toFixed(4)}</b><button onclick="delAlert(${a.id})">Excluir</button></div>`).join('')||'<div class="empty">Nenhum alerta criado.</div>'}
function tripCompanions(t){const out=[];try{const a=JSON.parse(t.companions||'[]');if(Array.isArray(a))out.push(...a.filter(Boolean))}catch{}if(Array.isArray(t.companion_names))out.push(...t.companion_names.filter(Boolean));return [...new Set(out.map(x=>String(x).trim()).filter(Boolean))]}function renderCompanionFields(){const n=Math.max(1,Math.min(30,Number($('#tTravelers')?.value||1))),box=$('#companionFields');if(!box)return;const count=n-1;box.classList.toggle('hidden',count===0);box.innerHTML=count?`<h4>Nomes dos acompanhantes</h4>${Array.from({length:count},(_,i)=>`<label>Acompanhante ${i+1}<input class="companionName" maxlength="100" required placeholder="Nome do acompanhante"></label>`).join('')}`:''}const travelerCountInput=$('#tTravelers');if(travelerCountInput){travelerCountInput.addEventListener('input',renderCompanionFields);travelerCountInput.addEventListener('change',renderCompanionFields)}function splitSelector(names){if(!names.length)return '<div class="muted">Cadastre acompanhantes na viagem para dividir este item.</div>';return `<div class="splitPicker">${names.map((n,i)=>`<label><input type="checkbox" class="budgetSplit" value="${esc(n)}"> <span>${esc(n)}</span></label>`).join('')}</div>`}async function openTrip(id,tab='overview'){currentTrip=await api('/api/trips/'+id);loadGoogleMaps().catch(()=>{});currentTab=tab;renderTrip();show('tripDetail')}async function refreshTrip(){const tab=currentTab;currentTrip=await api('/api/trips/'+currentTrip.trip.id);currentTab=tab;renderTrip()}function renderTrip(){const d=currentTrip,t=d.trip,bought=d.purchases.filter(p=>p.currency===t.currency).reduce((a,p)=>a+p.amount,0),pct=t.target_amount?Math.min(100,bought/t.target_amount*100):0;$('#tripHero').innerHTML=`<div class="tripHero"><div><span class="eyebrow">${esc(t.destinations)}</span><h1>${esc(t.name)}</h1><p>${brDate(t.start_date)} → ${t.end_date?brDate(t.end_date):'—'} · ${t.travelers} viajante(s) · Perfil ${esc(t.profile)}</p></div><div class="goal"><span>Meta cambial</span><strong>${fmt(bought)} / ${fmt(t.target_amount)} ${t.currency}</strong><div class="progress"><i style="width:${pct}%"></i></div><small>${pct.toFixed(0)}% concluído</small></div></div>`;updateTripNav();renderPanel()}function updateTripNav(){$$('.tripTabs [data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===currentTab));const groups={planning:['budget','itinerary','reservations','checklist'],discover:['map','explore'],organize:['documents','expenses','travelers']};$$('.tripGroupBtn').forEach(b=>b.classList.toggle('active',(groups[b.dataset.group]||[]).includes(currentTab)))}$$('.tripTabs [data-tab]').forEach(b=>b.onclick=async()=>{currentTab=b.dataset.tab;updateTripNav();$$('.tripTabGroup').forEach(g=>g.classList.remove('open'));const panel=$('#tripPanel');if(['map','explore','documents','expenses','travelers','assistant'].includes(currentTab))panel.innerHTML='<div class="empty">Carregando…</div>';try{await renderPanel()}catch(e){console.error('Falha ao abrir aba',currentTab,e);panel.innerHTML=`<div class="empty errorPanel"><b>Não foi possível abrir esta área.</b><span>${esc(e.message||'Erro inesperado.')}</span><button type="button" class="primary" id="retryTab">Tentar novamente</button></div>`;const r=$('#retryTab');if(r)r.onclick=()=>renderTrip()}});$$('.tripGroupBtn').forEach(b=>b.onclick=e=>{e.stopPropagation();const g=b.closest('.tripTabGroup'),was=g.classList.contains('open');$$('.tripTabGroup').forEach(x=>x.classList.remove('open'));if(!was)g.classList.add('open')});document.addEventListener('click',e=>{if(!e.target.closest('.tripTabGroup'))$$('.tripTabGroup').forEach(g=>g.classList.remove('open'))});function tripPlaces(t){return String(t.destinations||'').split(/[,;\n]+/).map(x=>x.trim()).filter(Boolean)}function placeOptions(t,selected=''){const a=tripPlaces(t);return a.map(x=>`<option value="${esc(x)}" ${x===selected?'selected':''}>${esc(x)}</option>`).join('')}function brDate(v){if(!v)return 'Sem data';const [y,m,d]=String(v).split('-');return d&&m&&y?`${d}/${m}/${y}`:v}function bulletNotes(v){return String(v||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean).map(x=>`• ${esc(x)}`).join(' &nbsp; ')}async function renderPanel(){const d=currentTrip,t=d.trip;if(currentTab==='overview'){const spent=d.budget.reduce((a,x)=>a+x.amount,0),res=d.reservations.reduce((a,x)=>a+x.amount_brl,0),done=d.checklist.filter(x=>x.done).length;$('#tripPanel').innerHTML=`<div class="stats"><div class="card"><span>Orçamento planejado</span><strong>${money(spent)}</strong></div><div class="card"><span>Reservas</span><strong>${d.reservations.length}</strong><small>${money(res)}</small></div><div class="card"><span>Checklist</span><strong>${done}/${d.checklist.length}</strong></div></div><div class="grid2"><div class="card"><h3>Próximos passos</h3><p>Complete seu orçamento, monte o roteiro e registre reservas para acompanhar tudo em um só lugar.</p></div><div class="card"><h3>Carteira da viagem</h3>${d.purchases.map(p=>`<div class="listItem"><b>${fmt(p.amount)} ${p.currency}</b><span>VET ${p.vet.toFixed(4)} · ${esc(p.provider)||'Fornecedor'}</span></div>`).join('')||'<div class="empty">Nenhuma compra vinculada.</div>'}</div></div>`}
if(currentTab==='budget'){const companions=tripCompanions(t);$('#tripPanel').innerHTML=`<div class="toolGrid"><form class="card" id="budgetForm"><h3>Adicionar ao orçamento</h3><label>País/Local<select id="bCountry" required><option value="">Selecione</option>${placeOptions(t)}</select></label><label>Categoria<select id="bCat"><option>Hospedagem</option><option>Alimentação</option><option>Transporte</option><option>Passeios</option><option>Compras</option><option>Seguro</option><option>Outros</option></select></label><label>Cidade<input id="bCity" maxlength="80" required placeholder="Ex.: Lisboa"></label><label>Descrição<input id="bDesc" required></label><label>Valor estimado (R$)<input id="bAmount" type="number" min="0" step="0.01" required></label><label>Dividir despesa</label>${splitSelector(companions)}<button class="primary">Adicionar</button></form><div><h3>Itens</h3>${d.budget.map(x=>{let sp=[];try{sp=JSON.parse(x.split_names||'[]')}catch{}return `<div class="listItem budgetItem"><div class="itemContent"><b>${esc(x.country||'Sem local')} · ${esc(x.category)}</b><span>${x.city?`<b>${esc(x.city)}:</b> `:''}${esc(x.description)}</span>${sp.length?`<span>Dividida com: ${esc(sp.join(', '))}</span>`:''}</div><b class="itemAmount">${money(x.amount)}</b><div class="itemActions"><button class="editBtn" onclick="editItem('budget',${x.id})">Editar</button><button class="removeBtn" onclick="delItem('budget',${x.id})">Remover</button></div></div>`}).join('')||'<div class="empty">Nenhum item.</div>'}</div></div>`;$('#budgetForm').onsubmit=e=>addTripItem(e,'budget',{country:$('#bCountry').value,category:$('#bCat').value,city:$('#bCity').value,description:$('#bDesc').value,amount:$('#bAmount').value,split_names:$$('.budgetSplit:checked').map(x=>x.value)})}
if(currentTab==='itinerary'){$('#tripPanel').innerHTML=`<div class="toolGrid"><form class="card" id="itinForm"><h3>Novo compromisso</h3><label>Data<input id="iDate" type="date"></label><label>País/Estado<select id="iTitle" required><option value="">Selecione</option>${placeOptions(t)}</select></label><label>Local<input id="iLocation" placeholder="Cidade, atração ou endereço"></label><label>Observações<textarea id="iNotes" placeholder="Uma observação por linha"></textarea></label><button class="primary">Adicionar</button></form><div><h3>Roteiro</h3>${d.itinerary.map(x=>`<div class="listItem itineraryItem"><div><b>${brDate(x.item_date)} · ${esc(x.title)}${x.location?' · '+esc(x.location):''}</b>${x.notes?`<span>${bulletNotes(x.notes)}</span>`:''}</div><div class="itemActions"><button class="editBtn" onclick="editItem('itinerary',${x.id})">Editar</button><button class="removeBtn" onclick="delItem('itinerary',${x.id})">Remover</button></div></div>`).join('')||'<div class="empty">Seu roteiro está vazio.</div>'}</div></div>`;$('#itinForm').onsubmit=e=>addTripItem(e,'itinerary',{item_date:$('#iDate').value,title:$('#iTitle').value,location:$('#iLocation').value,notes:$('#iNotes').value})}
if(currentTab==='reservations'){$('#tripPanel').innerHTML=`<div class="toolGrid"><form class="card" id="resForm"><h3>Nova reserva</h3><label>Tipo<select id="rKind"><option>Hotel</option><option>Voo</option><option>Trem</option><option>Seguro</option><option>Atração</option><option>Outro</option></select></label><label>Fornecedor<input id="rProvider"></label><label>Confirmação<input id="rConfirmation"></label><label>Valor (R$)<input id="rAmount" type="number" min="0" step="0.01"></label><button class="primary">Adicionar</button></form><div><h3>Reservas</h3>${d.reservations.map(x=>`<div class="listItem"><div><b>${esc(x.kind)} · ${esc(x.provider)||'Fornecedor'}</b><span>${esc(x.confirmation)||'Sem código'} · ${money(x.amount_brl)}</span></div><div class="itemActions"><button class="editBtn" onclick="editItem('reservations',${x.id})">Editar</button><button class="removeBtn" onclick="delItem('reservations',${x.id})">Remover</button></div></div>`).join('')||'<div class="empty">Nenhuma reserva registrada.</div>'}</div></div>`;$('#resForm').onsubmit=e=>addTripItem(e,'reservations',{kind:$('#rKind').value,provider:$('#rProvider').value,confirmation:$('#rConfirmation').value,amount_brl:$('#rAmount').value||0,status:'confirmada'})}
if(currentTab==='checklist'){$('#tripPanel').innerHTML=`<div class="toolGrid"><form class="card" id="checkForm"><h3>Novo item</h3><label>O que precisa fazer?<input id="cTitle" required placeholder="Contratar seguro viagem"></label><button class="primary">Adicionar</button></form><div><h3>Checklist</h3>${d.checklist.map(x=>`<div class="check"><input type="checkbox" ${x.done?'checked':''} onchange="toggleCheck(${x.id},this.checked)"><span class="${x.done?'done':''}">${esc(x.title)}</span><div class="itemActions"><button class="editBtn" onclick="editItem('checklist',${x.id})">Editar</button><button class="removeBtn" onclick="delItem('checklist',${x.id})">Remover</button></div></div>`).join('')||'<div class="empty">Checklist vazio.</div>'}</div></div>`;$('#checkForm').onsubmit=e=>addTripItem(e,'checklist',{title:$('#cTitle').value})}
if(['map','explore','documents','expenses','travelers','assistant'].includes(currentTab))await renderAdvancedPanel(currentTab);
}
async function addTripItem(e,type,data){e.preventDefault();await api('/api/'+type,{method:'POST',body:JSON.stringify({trip_id:currentTrip.trip.id,...data})});await refreshTrip()}async function delItem(type,id){await api(`/api/${type}/${id}`,{method:'DELETE'});await refreshTrip()}async function toggleCheck(id,done){await api('/api/checklist/'+id,{method:'PATCH',body:JSON.stringify({done})});await refreshTrip()}
async function toolRows(type){return api(`/api/trip-tools?trip_id=${currentTrip.trip.id}&type=${type}`)}async function addTool(type,data){await api('/api/trip-tools',{method:'POST',body:JSON.stringify({trip_id:currentTrip.trip.id,type,data})});renderAdvancedPanel(currentTab)}async function delTool(id){await api('/api/trip-tools/'+id,{method:'DELETE'});renderAdvancedPanel(currentTab)}
function editField(label,control){return `<label>${label}${control}</label>`}
function openEditModal(title,fields,onSave){const dlg=$('#editDialog'),form=$('#editForm');$('#editTitle').textContent=title;$('#editFields').innerHTML=fields;$('#editMsg').textContent='';form.onsubmit=async e=>{e.preventDefault();try{await onSave();dlg.close()}catch(err){$('#editMsg').textContent=err.message}};dlg.showModal()}
function closeEditModal(){const d=$('#editDialog');if(d?.open)d.close()}const editCancel=$('#editCancel');if(editCancel)editCancel.onclick=closeEditModal;const editClose=$('#editDialog .close');if(editClose)editClose.onclick=closeEditModal;
function closeDocumentViewer(){const d=$('#documentViewerDialog'),body=$('#documentViewerBody');if(body)body.innerHTML='';if(d?.open)d.close()}const documentViewerClose=$('#documentViewerClose');if(documentViewerClose)documentViewerClose.onclick=closeDocumentViewer;async function viewDocument(id,name,mime){const dlg=$('#documentViewerDialog'),body=$('#documentViewerBody');$('#documentViewerTitle').textContent=name||'Visualizar documento';body.innerHTML='<div class="empty">Carregando documento…</div>';if(!dlg.open)dlg.showModal();try{const r=await fetch(`/api/documents/${id}/file`,{credentials:'same-origin'});if(!r.ok){let msg='Não foi possível abrir o documento.';try{const j=await r.json();msg=j.error||msg}catch{}throw new Error(msg)}const blob=await r.blob(),url=URL.createObjectURL(blob);body.innerHTML='';if((mime||blob.type).startsWith('image/')){const img=document.createElement('img');img.className='documentPreviewImage';img.alt=name||'Documento';img.src=url;img.onload=()=>URL.revokeObjectURL(url);body.appendChild(img)}else{const frame=document.createElement('iframe');frame.className='documentPreviewFrame';frame.title=name||'Documento';frame.src=url;frame.onload=()=>setTimeout(()=>URL.revokeObjectURL(url),1000);body.appendChild(frame)}}catch(e){body.innerHTML=`<div class="empty errorPanel">${esc(e.message)}</div>`}}
function selectedSplit(names,selected,cls){return `<div class="splitPicker">${names.map(n=>`<label><input type="checkbox" class="${cls}" value="${esc(n)}" ${selected.includes(n)?'checked':''}> <span>${esc(n)}</span></label>`).join('')}</div>`}
async function editItem(type,id){const map={budget:currentTrip.budget,itinerary:currentTrip.itinerary,reservations:currentTrip.reservations,checklist:currentTrip.checklist},x=(map[type]||[]).find(r=>Number(r.id)===Number(id));if(!x)return alert('Item não encontrado.');if(type==='budget'){let split=[];try{split=JSON.parse(x.split_names||'[]')}catch{}const companions=tripCompanions(currentTrip.trip);openEditModal('Editar orçamento',editField('País/Local',`<select id="ebCountry" required><option value="">Selecione</option>${placeOptions(currentTrip.trip,x.country)}</select>`)+editField('Categoria',`<select id="ebCat">${['Hospedagem','Alimentação','Transporte','Passeios','Compras','Seguro','Outros'].map(v=>`<option ${v===x.category?'selected':''}>${v}</option>`).join('')}</select>`)+editField('Cidade',`<input id="ebCity" maxlength="80" required value="${esc(x.city||'')}">`)+editField('Descrição',`<input id="ebDesc" required value="${esc(x.description||'')}">`)+editField('Valor estimado (R$)',`<input id="ebAmount" type="number" min="0" step="0.01" required value="${Number(x.amount||0)}">`)+`<label>Dividir despesa</label>${companions.length?selectedSplit(companions,split,'editBudgetSplit'):'<div class="muted">Cadastre acompanhantes na viagem para dividir este item.</div>'}`,async()=>{await api(`/api/budget/${id}`,{method:'PUT',body:JSON.stringify({country:$('#ebCountry').value,category:$('#ebCat').value,city:$('#ebCity').value,description:$('#ebDesc').value,amount:$('#ebAmount').value,split_names:$$('.editBudgetSplit:checked').map(v=>v.value)})});await refreshTrip()});return}
if(type==='itinerary'){openEditModal('Editar compromisso',editField('Data',`<input id="eiDate" type="date" value="${esc(x.item_date||'')}">`)+editField('País/Estado',`<select id="eiTitle" required><option value="">Selecione</option>${placeOptions(currentTrip.trip,x.title)}</select>`)+editField('Local',`<input id="eiLocation" value="${esc(x.location||'')}" placeholder="Cidade, atração ou endereço">`)+editField('Observações',`<textarea id="eiNotes" placeholder="Uma observação por linha">${esc(x.notes||'')}</textarea>`),async()=>{await api(`/api/itinerary/${id}`,{method:'PUT',body:JSON.stringify({item_date:$('#eiDate').value,title:$('#eiTitle').value,location:$('#eiLocation').value,notes:$('#eiNotes').value})});await refreshTrip()});return}
if(type==='reservations'){openEditModal('Editar reserva',editField('Tipo',`<select id="erKind">${['Hotel','Voo','Trem','Seguro','Atração','Outro'].map(v=>`<option ${v===x.kind?'selected':''}>${v}</option>`).join('')}</select>`)+editField('Fornecedor',`<input id="erProvider" value="${esc(x.provider||'')}">`)+editField('Confirmação',`<input id="erConfirmation" value="${esc(x.confirmation||'')}">`)+editField('Valor (R$)',`<input id="erAmount" type="number" min="0" step="0.01" value="${Number(x.amount_brl||0)}">`),async()=>{await api(`/api/reservations/${id}`,{method:'PUT',body:JSON.stringify({kind:$('#erKind').value,provider:$('#erProvider').value,confirmation:$('#erConfirmation').value,amount_brl:$('#erAmount').value||0,status:x.status||'confirmada'})});await refreshTrip()});return}
openEditModal('Editar item do checklist',editField('O que precisa fazer?',`<input id="ecTitle" required value="${esc(x.title||'')}">`),async()=>{await api(`/api/checklist/${id}`,{method:'PUT',body:JSON.stringify({title:$('#ecTitle').value})});await refreshTrip()})}
async function editTool(id,type){const rows=await toolRows(type),x=rows.find(r=>Number(r.id)===Number(id));if(!x)return alert('Item não encontrado.');const d=x.data||{},save=async data=>{await api('/api/trip-tools/'+id,{method:'PUT',body:JSON.stringify({data})});if(type==='collaborator')await refreshTrip();else await renderAdvancedPanel(currentTab)};if(type==='document'){openEditModal('Editar documento',editField('Tipo',`<select id="edType">${['Passagem','Voucher','Seguro viagem','Ingresso','Reserva','Passaporte','Outro'].map(v=>`<option ${v===d.type?'selected':''}>${v}</option>`).join('')}</select>`)+editField('Nome',`<input id="edName" required value="${esc(d.name||'')}">`)+(d.filename?`<div class="fileInfo"><b>Arquivo armazenado</b><span>${esc(d.filename)}</span><small>Para trocar o arquivo, remova este documento e envie o novo arquivo.</small></div>`:'')+editField('Observações',`<textarea id="edNotes">${esc(d.notes||'')}</textarea>`),()=>save({...d,type:$('#edType').value,name:$('#edName').value,notes:$('#edNotes').value}));return}if(type==='expense'){const companions=tripCompanions(currentTrip.trip),people=[me?.name||'Usuário principal',...companions],split=Array.isArray(d.splitNames)?d.splitNames:String(d.split||'').split(',').map(v=>v.trim()).filter(Boolean);openEditModal('Editar despesa',editField('Descrição',`<input id="eeDesc" required value="${esc(d.description||'')}">`)+`<div class="row">${editField('Valor',`<input id="eeAmount" type="number" min="0" step="0.01" required value="${Number(d.amount||0)}">`)}${editField('Moeda',`<select id="eeCur">${['BRL',currentTrip.trip.currency,'EUR','USD'].filter((v,i,a)=>a.indexOf(v)===i).map(v=>`<option ${v===d.currency?'selected':''}>${v}</option>`).join('')}</select>`)}</div>`+editField('Pago por',`<select id="eePaid">${people.map(n=>`<option ${n===d.paidBy?'selected':''}>${esc(n)}</option>`).join('')}</select>`)+`<label>Dividir entre</label>${selectedSplit(people,split,'editExpenseSplit')}`,()=>{const names=$$('.editExpenseSplit:checked').map(v=>v.value);return save({...d,description:$('#eeDesc').value,amount:Number($('#eeAmount').value),currency:$('#eeCur').value,paidBy:$('#eePaid').value,split:names.join(', '),splitNames:names})});return}if(type==='collaborator'){openEditModal('Editar viajante',editField('Nome',`<input id="ecoName" required value="${esc(d.name||'')}">`)+editField('E-mail',`<input id="ecoEmail" type="email" value="${esc(d.email||'')}">`)+editField('Permissão',`<select id="ecoRole">${['Somente visualizar','Pode editar'].map(v=>`<option ${v===d.role?'selected':''}>${v}</option>`).join('')}</select>`),()=>save({...d,name:$('#ecoName').value,email:$('#ecoEmail').value,role:$('#ecoRole').value}));return}}
async function renderAdvancedPanel(tab){const box=$('#tripPanel'),t=currentTrip.trip;if(tab==='map'){const days=itineraryDays();let savedChoices=[];try{savedChoices=await toolRows('route_choice')}catch(e){console.warn('Escolhas de rota indisponíveis',e)}const opts=days.map(([d,items])=>`<option value="${esc(d)}">${d==='sem-data'?'Sem data':brDate(d)} · ${esc(items[0]?.title||items[0]?.location||'Roteiro')}</option>`).join('');box.innerHTML=`<div class="mapDayToolbar card"><label>Dia do roteiro<select id="mapDay"><option value="all">Todos os dias</option>${opts}</select></label><label>Transporte<select id="routeMode"><option value="WALK">A pé</option><option value="DRIVE">Carro</option><option value="BICYCLE">Bicicleta</option><option value="TRANSIT">Transporte público</option></select></label><button class="primary" id="buildDayRoute">Montar roteiro visual</button></div><div class="mapLayout"><div class="card"><h3>Mapa da viagem</h3><div id="tripGoogleMap" class="tripMap"><div class="mapLoading">Carregando Google Maps…</div></div><p id="mapStatus" class="muted">Escolha um dia para transformar as paradas do Roteiro em um trajeto visual.</p><div id="routeSummary"></div></div><div><h3>Paradas do dia</h3><div id="dayStops"><div class="empty">Selecione um dia e clique em “Montar roteiro visual”.</div></div></div></div>`;await initTripGoogleMap([],t);const build=async()=>{const chosen=$('#mapDay').value,mode=$('#routeMode').value,status=$('#mapStatus'),list=$('#dayStops'),summary=$('#routeSummary');summary.innerHTML='';status.textContent='Localizando as paradas no Google Places…';const items=chosen==='all'?currentTrip.itinerary:(days.find(([d])=>d===chosen)?.[1]||[]);const resolved=await resolveDayStops(items,t);for(let i=0;i<resolved.stops.length;i++){const s=resolved.stops[i];if(!s.ambiguous)continue;const saved=savedChoices.find(x=>x.data?.date===chosen&&x.data?.prompt===s.label);if(saved?.data?.address)resolved.stops[i]={label:saved.data.label,address:saved.data.address,location:{lat:Number(saved.data.lat),lng:Number(saved.data.lng)}}}window.ihResolvedStops=resolved.stops;const renderList=()=>{let order=0;list.innerHTML=resolved.stops.map((s,i)=>{if(s.ambiguous)return `<div class="listItem ambiguity"><div><b>Escolha o local</b><span>${esc(s.label)}</span><select class="ambiguityChoice" data-i="${i}"><option value="">Selecione…</option>${s.choices.map((c,j)=>`<option value="${j}">${esc(c.label)} · ${esc(c.address)}</option>`).join('')}</select></div></div>`;order++;return `<div class="listItem"><div class="routeNumber">${order}</div><div><b>${esc(s.label)}</b><span>${esc(s.address)}</span></div></div>`}).join('')+(resolved.unresolved.length?`<div class="empty">Não localizados automaticamente: ${esc(resolved.unresolved.join(', '))}</div>`:'')||'<div class="empty">Nenhuma parada identificada neste dia.</div>';list.querySelectorAll('.ambiguityChoice').forEach(sel=>sel.onchange=()=>{const i=Number(sel.dataset.i),j=Number(sel.value);if(!Number.isFinite(j))return;const prompt=resolved.stops[i].label,c=resolved.stops[i].choices[j];resolved.stops[i]={label:c.label,address:c.address,location:c.location};const lat=typeof c.location?.lat==='function'?c.location.lat():c.location?.lat,lng=typeof c.location?.lng==='function'?c.location.lng():c.location?.lng;api('/api/trip-tools',{method:'POST',body:JSON.stringify({trip_id:t.id,type:'route_choice',data:{date:chosen,prompt,label:c.label,address:c.address,lat,lng}})}).then(x=>savedChoices.unshift({data:{date:chosen,prompt,label:c.label,address:c.address,lat,lng}})).catch(e=>console.warn('Não foi possível salvar escolha',e));renderList();drawDayMarkers(resolved.stops)})};renderList();await drawDayMarkers(resolved.stops);const ready=resolved.stops.filter(s=>!s.ambiguous&&s.address);const pending=resolved.stops.filter(s=>s.ambiguous).length;if(pending){status.textContent=`${ready.length} parada(s) localizada(s). Escolha ${pending} local(is) genérico(s) antes de calcular a rota.`;return}if(ready.length<2){status.textContent='Não há pelo menos duas paradas localizadas para montar a rota.';return}status.textContent=`${ready.length} paradas localizadas. Calculando distâncias e trajeto real…`;try{const r=await api('/api/routes/compute',{method:'POST',body:JSON.stringify({trip_id:t.id,mode,points:ready.map(x=>({label:x.label,address:x.address}))})});await drawGoogleRoute(r);const km=r.distance_meters/1000,mins=Math.round(r.duration_seconds/60);summary.innerHTML=`<div class="routeResult"><b>${fmt(km,1)} km · ${formatRouteDuration(mins)}</b><span>${esc(r.points.join(' → '))}</span><small>Google Places + Google Routes</small></div>`;status.textContent=`Roteiro visual pronto: ${ready.length} paradas na ordem do dia.`}catch(e){summary.innerHTML=`<div class="empty errorPanel">${esc(e.message)}</div>`;status.textContent='As paradas foram localizadas, mas a rota não pôde ser calculada.'}};$('#buildDayRoute').onclick=()=>build().catch(e=>{$('#mapStatus').textContent=e.message});if(days.length){$('#mapDay').value=days[0][0];build().catch(e=>{$('#mapStatus').textContent=e.message})}return}
if(tab==='explore'){box.innerHTML=`<div class="card"><h3>Explorar lugares</h3><p>Pesquise lugares reais no Google Places dentro do destino selecionado e salve na viagem.</p><div class="row"><label>Destino<select id="exDest">${placeOptions(t)}</select></label><label>O que procura?<input id="exQuery" placeholder="restaurantes, museus, atrações..."></label></div><button class="primary" id="exSearch">Pesquisar</button></div><div id="exploreResults"></div>`;$('#exSearch').onclick=async()=>{const dest=$('#exDest').value,q=$('#exQuery').value.trim()||'atrações';const out=$('#exploreResults');out.innerHTML='<div class="empty">Pesquisando no Google Places…</div>';try{await loadGoogleMaps();const {Place}=await google.maps.importLibrary('places');const regionCodes={'Portugal':'pt','Espanha':'es','Itália':'it','Suíça':'ch','França':'fr','Alemanha':'de','Reino Unido':'gb','Estados Unidos':'us','Brasil':'br','Grécia':'gr','Turquia':'tr','Albânia':'al'};const request={textQuery:`${q} em ${dest}`,fields:['id','displayName','formattedAddress','addressComponents','rating','userRatingCount','googleMapsURI','primaryTypeDisplayName','photos'],maxResultCount:20,language:'pt-BR'};if(regionCodes[dest])request.region=regionCodes[dest];const r=await Place.searchByText(request);const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const wanted=norm(dest);const rows=(r.places||[]).filter(x=>{const country=x.addressComponents?.find(c=>(c.types||[]).includes('country'));const countryName=country?.longText||country?.shortText||'';return norm(countryName)===wanted||norm(x.formattedAddress).includes(wanted)}).slice(0,12);if(!rows.length){out.innerHTML=`<div class="empty">Nenhum resultado confirmado dentro de ${esc(dest)} para essa busca. Tente outro termo.</div>`;return}out.innerHTML='<div class="exploreGrid">'+rows.map((x,i)=>{let image='';try{image=x.photos?.[0]?.getURI?x.photos[0].getURI({maxWidth:800}):''}catch{}const title=x.displayName||'';const cat=x.primaryTypeDisplayName||'Local';const map=x.googleMapsURI||('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(title+' '+dest));return `<article class="card placeCard">${image?`<img src="${esc(image)}" alt="${esc(title)}" loading="lazy">`:''}<h3>${esc(title)}</h3><p>${esc(cat)} · ${esc(x.formattedAddress||'Endereço não informado')}</p>${x.rating?`<p class="muted">★ ${fmt(x.rating,1)} · ${fmt(x.userRatingCount||0,0)} avaliações no Google</p>`:''}<div class="actions"><a class="quoteBtn" target="_blank" rel="noopener" href="${esc(map)}">Ver mapa</a><button class="primary savePlace" data-i="${i}">+ Salvar</button></div></article>`}).join('')+'</div>';out.querySelectorAll('.savePlace').forEach(b=>b.onclick=()=>{const x=rows[Number(b.dataset.i)];addTool('place',{placeId:x.id||'',name:x.displayName||'',country:dest,address:x.formattedAddress||'',mapUrl:x.googleMapsURI||''})})}catch(e){console.error(e);out.innerHTML=`<div class="empty">${esc(e.message||'Não foi possível consultar o Google Places agora.')}</div>`}};return}
if(tab==='documents'){const rows=await toolRows('document');box.innerHTML=`<div class="toolGrid"><form class="card" id="docForm"><h3>Documentos e vouchers</h3><label>Tipo<select id="docType"><option>Passagem</option><option>Voucher</option><option>Seguro viagem</option><option>Ingresso</option><option>Reserva</option><option>Passaporte</option><option>Outro</option></select></label><label>Nome<input id="docName" required placeholder="Ex.: Seguro viagem Europa"></label><label>Arquivo<input id="docFile" type="file" accept="application/pdf,image/jpeg,image/png,.pdf,.jpg,.jpeg,.png" required></label><small class="muted">PDF, JPG ou PNG · máximo 8 MB. O arquivo será privado e vinculado somente a esta viagem.</small><label>Observações<textarea id="docNotes"></textarea></label><button class="primary" id="docSubmit">Enviar documento</button><p class="error" id="docMsg"></p></form><div><h3>Documentos</h3>${rows.map(x=>`<div class="listItem documentItem"><div><b>${esc(x.data.type)} · ${esc(x.data.name)}</b><span>${esc(x.data.filename||'')}${x.data.size?' · '+fmt(x.data.size/1024,0)+' KB':''}</span><span>${esc(x.data.notes||'')}</span></div>${x.data.storagePath?`<button type="button" class="quoteBtn" onclick="viewDocument(${x.id},'${esc(x.data.name).replace(/'/g,"&#39;")}','${esc(x.data.mime||"")}')">Visualizar</button>`:(x.data.url?`<a class="quoteBtn" target="_blank" rel="noopener" href="${esc(x.data.url)}">Abrir legado ↗</a>`:'')}<div class="itemActions"><button class="editBtn" onclick="editTool(${x.id},'document')">Editar</button><button class="removeBtn" onclick="delTool(${x.id})">Remover</button></div></div>`).join('')||'<div class="empty">Nenhum documento.</div>'}</div></div>`;$('#docForm').onsubmit=async e=>{e.preventDefault();const f=$('#docFile').files?.[0],msg=$('#docMsg'),btn=$('#docSubmit');msg.textContent='';if(!f)return msg.textContent='Selecione um arquivo.';if(f.size>8*1024*1024)return msg.textContent='O arquivo deve ter no máximo 8 MB.';if(!['application/pdf','image/jpeg','image/png'].includes(f.type))return msg.textContent='Envie um arquivo PDF, JPG ou PNG.';btn.disabled=true;btn.textContent='Enviando…';try{const base64=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]||'');r.onerror=reject;r.readAsDataURL(f)});await api('/api/documents/upload',{method:'POST',body:JSON.stringify({trip_id:t.id,type:$('#docType').value,name:$('#docName').value,notes:$('#docNotes').value,filename:f.name,mime:f.type,base64})});await renderAdvancedPanel('documents')}catch(err){msg.textContent=err.message;btn.disabled=false;btn.textContent='Enviar documento'}};return}
if(tab==='expenses'){const rows=await toolRows('expense'),total=rows.reduce((a,x)=>a+Number(x.data.amount||0),0),companions=tripCompanions(t),people=[me?.name||'Usuário principal',...companions];box.innerHTML=`<div class="stats"><div class="card"><span>Despesas registradas</span><strong>${money(total)}</strong></div><div class="card"><span>Por viajante</span><strong>${money(total/Math.max(1,t.travelers))}</strong></div></div><div class="toolGrid"><form class="card" id="expForm"><h3>Registrar despesa</h3><label>Descrição<input id="eDesc" required></label><div class="row"><label>Valor<input id="eAmount" type="number" min="0" step="0.01" required></label><label>Moeda<select id="eCur"><option>BRL</option><option>${t.currency}</option><option>EUR</option><option>USD</option></select></label></div><label>Pago por<select id="ePaid">${people.map(n=>`<option>${esc(n)}</option>`).join('')}</select></label><label>Dividir entre</label><div class="splitPicker">${people.map(n=>`<label><input type="checkbox" class="expenseSplit" value="${esc(n)}"> <span>${esc(n)}</span></label>`).join('')}</div><button class="primary">Adicionar</button></form><div><h3>Divisão de despesas</h3>${rows.map(x=>`<div class="listItem expenseItem"><div><b>${esc(x.data.description)}</b><span>Pago por ${esc(x.data.paidBy||'—')}</span><span>Dividir: ${esc(x.data.split||'todos')}</span>${x.data.source==='budget'?'<small>Importada automaticamente do Orçamento</small>':''}</div><b>${x.data.currency==='BRL'?money(x.data.amount):fmt(x.data.amount)+' '+esc(x.data.currency)}</b><div class="itemActions"><button class="editBtn" onclick="editTool(${x.id},'expense')">Editar</button><button class="removeBtn" onclick="delTool(${x.id})">Remover</button></div></div>`).join('')||'<div class="empty">Nenhuma despesa.</div>'}</div></div>`;$('#expForm').onsubmit=e=>{e.preventDefault();const names=$$('.expenseSplit:checked').map(x=>x.value);addTool('expense',{description:$('#eDesc').value,amount:Number($('#eAmount').value),currency:$('#eCur').value,paidBy:$('#ePaid').value,split:names.join(', '),splitNames:names})};return}
if(tab==='travelers'){const rows=await toolRows('collaborator'),companions=tripCompanions(t);box.innerHTML=`<div class="toolGrid"><form class="card" id="colForm"><h3>Viajantes e colaboração</h3><label>Nome<input id="coName" required></label><label>E-mail<input id="coEmail" type="email"></label><label>Permissão<select id="coRole"><option>Somente visualizar</option><option>Pode editar</option></select></label><button class="primary">Adicionar viajante</button><p class="muted">A lista organiza participantes e permissões. O compartilhamento por login depende de o e-mail possuir conta na plataforma.</p></form><div><h3>Participantes</h3><div class="listItem"><div><b>${esc(me?.name||'Usuário principal')}</b><span>Titular da viagem</span></div></div>${rows.map(x=>`<div class="listItem"><div><b>${esc(x.data.name)}</b><span>${esc(x.data.email||'')} · ${esc(x.data.role)}</span></div><div class="itemActions"><button class="editBtn" onclick="editTool(${x.id},'collaborator')">Editar</button><button class="removeBtn" onclick="delTool(${x.id})">Remover</button></div></div>`).join('')||(!companions.length?'<div class="empty">Nenhum acompanhante cadastrado.</div>':'')}</div></div>`;$('#colForm').onsubmit=e=>{e.preventDefault();addTool('collaborator',{name:$('#coName').value,email:$('#coEmail').value,role:$('#coRole').value})};return}
if(tab==='assistant'){box.innerHTML=`<div class="assistantBox card"><span class="eyebrow">Assistente Ih, viajei!</span><h3>Pergunte sobre sua própria viagem</h3><p class="muted">Esta área só responde quando a integração real com a API de IA estiver configurada. Não exibimos respostas simuladas.</p><textarea id="asQ" rows="4" placeholder="Ex.: Ainda preciso comprar moeda. Como organizar minhas compras?"></textarea><button class="primary" id="asAsk">Perguntar</button><div id="asAnswer"></div></div>`;$('#asAsk').onclick=async()=>{const out=$('#asAnswer');out.innerHTML='<div class="empty">Consultando…</div>';try{const d=await api('/api/travel-assistant',{method:'POST',body:JSON.stringify({trip_id:t.id,question:$('#asQ').value})});out.innerHTML=`<div class="assistantAnswer"><b>Resposta</b><p>${esc(d.answer)}</p></div>`}catch(e){out.innerHTML=`<div class="empty">${esc(e.message)}</div>`}};return}}
$('#purchaseForm').onsubmit=async e=>{e.preventDefault();await api('/api/purchases',{method:'POST',body:JSON.stringify({trip_id:$('#purchaseTrip').value,currency:$('#pCurrency').value,amount:$('#pAmount').value,total_brl:$('#pTotal').value,provider:$('#pProvider').value,purchased_at:$('#pDate').value})});e.target.reset();$('#pDate').value=new Date().toISOString().slice(0,10);loadDashboard()};$('#alertForm').onsubmit=async e=>{e.preventDefault();await api('/api/alerts',{method:'POST',body:JSON.stringify({currency:$('#aCurrency').value,kind:$('#aKind').value,threshold:$('#aThreshold').value})});e.target.reset();loadDashboard()};async function delTrip(id){if(confirm('Excluir esta viagem?')){await api('/api/trips/'+id,{method:'DELETE'});loadDashboard()}}async function delAlert(id){await api('/api/alerts/'+id,{method:'DELETE'});loadDashboard()}
async function loadRadar(c){const k=c.toLowerCase(),cap=k[0].toUpperCase()+k.slice(1),btn=document.querySelector(`[data-radar="${c}"]`),set=(id,value)=>{const el=$('#'+id);if(el)el.textContent=value};if(btn){btn.disabled=true;btn.textContent='Atualizando…'}try{const d=await api('/api/rates/history?currency='+c+'&days=30'),rate=`R$ ${Number(d.summary.current).toLocaleString('pt-BR',{minimumFractionDigits:4,maximumFractionDigits:4})}`,score=`Radar ${d.summary.score}/100 · ${d.summary.label}`,source=`30 dias: mín. R$ ${d.summary.min.toFixed(4)} · média R$ ${d.summary.average.toFixed(4)} · máx. R$ ${d.summary.max.toFixed(4)} · Fonte: ${d.source}`;set(k+'Rate',rate);set(k+'Score',score);set(k+'Source',source);set('home'+cap+'Rate',rate);set('home'+cap+'Score',score);set('home'+cap+'Source',source)}catch(e){set(k+'Rate','Indisponível');set(k+'Score','Radar indisponível');set(k+'Source',e.message);set('home'+cap+'Rate','Indisponível');set('home'+cap+'Score','Radar indisponível');set('home'+cap+'Source',e.message)}finally{if(btn){btn.disabled=false;btn.textContent='↻ Atualizar análise'}}}
async function loadVetInfo(currency='EUR'){const box=$('#vetInfo'),btn=$('#vetRefresh');if(!box)return;if(btn){btn.disabled=true;btn.textContent='Atualizando…'}box.innerHTML='<div class="empty">Consultando o Banco Central…</div>';try{const d=await api('/api/vet/reference?currency='+currency);const month=d.reference?`${d.reference.slice(0,2)}/${d.reference.slice(2)}`:'—';box.innerHTML=`<div class="vetToolbar"><div><b>${d.currency}/BRL · referência ${month}</b><small>Ranking histórico oficial do Banco Central</small></div><div class="currencySwitch"><button type="button" data-vet-currency="EUR" class="${d.currency==='EUR'?'active':''}">Euro</button><button type="button" data-vet-currency="USD" class="${d.currency==='USD'?'active':''}">Dólar</button></div></div><div class="vetTable"><div class="vetRow vetHeader"><span>Instituição</span><span>VET médio</span><span>Operações</span><span>Ação</span></div>${d.rows.map((x,i)=>`<div class="vetRow"><span><b>${i+1}. ${esc(x.institution)}</b></span><span>R$ ${Number(x.vet).toLocaleString('pt-BR',{minimumFractionDigits:4,maximumFractionDigits:4})}</span><span>${Number(x.operations).toLocaleString('pt-BR')}</span><span>${x.action_url?`<a class="quoteBtn" href="${esc(x.action_url)}" target="_blank" rel="noopener noreferrer">Consultar cotação ↗</a>`:`<a class="quoteBtn secondary" href="${esc(x.bcb_url||d.url)}" target="_blank" rel="noopener noreferrer">Ver instituição ↗</a>`}</span></div>`).join('')}</div><p class="vetNote">${esc(d.notice)}</p><a class="externalBtn" href="${esc(d.url)}" target="_blank" rel="noopener">Ver conjunto oficial no Banco Central ↗</a>`;box.querySelectorAll('[data-vet-currency]').forEach(x=>x.addEventListener('click',()=>loadVetInfo(x.dataset.vetCurrency)))}catch(e){box.innerHTML=`<div class="empty">${esc(e.message)}</div>`}finally{if(btn){btn.disabled=false;btn.textContent='↻ Atualizar dados'}}}
let adminUserRows=[];async function loadAdmin(){if(me?.role!=='admin')return;const [s,users]=await Promise.all([api('/api/admin/stats'),api('/api/admin/users')]);adminUserRows=users;$('#adminStats').innerHTML=[['Usuários',s.users],['Viagens cadastradas',s.trips],['Compras de moeda',s.purchases],['Total registrado',money(s.invested)]].map(([a,b])=>`<div class="card"><span>${a}</span><strong>${b}</strong></div>`).join('');const max=Math.max(1,...s.months.map(x=>x.users));$('#usersChart').innerHTML=s.months.length?s.months.map(x=>`<div class="barCol"><div class="barValue">${x.users}</div><i style="height:${Math.max(8,x.users/max*120)}px"></i><small>${monthLabel(x.month)}</small></div>`).join(''):'<div class="empty">Ainda não há histórico suficiente.</div>';const total=Math.max(1,s.plans.reduce((a,x)=>a+x.n,0));$('#plansChart').innerHTML=['gratuito','intermediario','pro'].map(plan=>{const row=s.plans.find(x=>x.plan===plan),n=row?.n||0;return `<div class="planBarRow"><div><b>${plan==='intermediario'?'Intermediário':plan==='pro'?'PRO':'Gratuito'}</b><span>${n} usuário(s)</span></div><div class="planTrack"><i style="width:${n/total*100}%"></i></div><strong>${Math.round(n/total*100)}%</strong></div>`}).join('');renderAdminUsers(users);const search=$('#adminUserSearch');if(search&&!search.dataset.bound){search.dataset.bound='1';search.addEventListener('input',()=>{const q=search.value.toLowerCase().trim();renderAdminUsers(adminUserRows.filter(u=>!q||u.name.toLowerCase().includes(q)||u.email.toLowerCase().includes(q)))})}}function monthLabel(v){const [y,m]=String(v).split('-');return `${m}/${String(y).slice(-2)}`}function renderAdminUsers(users){$('#adminUsers').innerHTML=users.length?`<div class="adminTable"><div class="adminRow adminRowHead"><span>Usuário</span><span>Plano</span><span>Cadastro</span><span>Viagens</span><span>Compras</span><span>Ações</span></div>${users.map(u=>`<div class="adminRow"><span><b>${esc(u.name)}</b><small>${esc(u.email)}</small></span><span><select class="adminPlanSelect" onchange="adminSetPlan(${u.id},this.value)"><option value="gratuito" ${u.plan==='gratuito'?'selected':''}>Gratuito</option><option value="intermediario" ${u.plan==='intermediario'?'selected':''}>Intermediário</option><option value="pro" ${u.plan==='pro'?'selected':''}>PRO</option></select></span><span>${brDate(String(u.created_at).slice(0,10))}</span><span>${u.trips}</span><span>${u.purchases}</span><span><button class="danger mini" onclick="adminDeleteUser(${u.id},'${esc(u.name).replace(/'/g,'&#39;')}')">Excluir</button></span></div>`).join('')}</div>`:'<div class="empty">Nenhum usuário encontrado.</div>'}async function adminSetPlan(id,plan){try{await api('/api/admin/users/'+id,{method:'PATCH',body:JSON.stringify({plan})});await loadAdmin()}catch(e){alert(e.message);await loadAdmin()}}async function adminDeleteUser(id,name){if(!confirm(`Excluir o usuário ${name} e todos os dados vinculados?`))return;try{await api('/api/admin/users/'+id,{method:'DELETE'});await loadAdmin()}catch(e){alert(e.message)}}
function bindPlanButtons(){document.querySelectorAll('.planBtn').forEach(btn=>btn.addEventListener('click',async()=>{const plan=btn.dataset.plan;if(!me){openAuth('register');return}if(me.role==='admin'){alert('Planos são destinados às contas de viajantes.');return}try{const d=await api('/api/plans/select',{method:'POST',body:JSON.stringify({plan})});if(d.checkout_url){window.location.href=d.checkout_url;return}me=await api('/api/me');alert(plan==='gratuito'?'Plano Gratuito selecionado.':'Plano selecionado.')}catch(e){alert(e.message)}}));const c=$('#ctaStart');if(c)c.onclick=()=>openAuth('register')}bindPlanButtons();document.querySelectorAll('[data-radar]').forEach(b=>b.addEventListener('click',()=>loadRadar(b.dataset.radar)));const vetRefresh=$('#vetRefresh');if(vetRefresh)vetRefresh.addEventListener('click',()=>loadVetInfo());Object.assign(window,{openTrip,delTrip,delAlert,delItem,delTool,editItem,editTool,viewDocument,toggleCheck,loadRadar,loadVetInfo,adminSetPlan,adminDeleteUser});init();

