function setupCountryPicker(){const box=$('#countryOptions'),search=$('#countrySearch'),hidden=$('#tDest'),summary=$('#countrySummary');if(!box||box.dataset.ready)return;box.dataset.ready='1';const render=q=>{const selected=new Set((hidden.value||'').split(',').map(x=>x.trim()).filter(Boolean));box.innerHTML=COUNTRIES.filter(c=>!q||c.toLocaleLowerCase('pt-BR').includes(q.toLocaleLowerCase('pt-BR'))).map(c=>`<label class="countryOption"><input type="checkbox" value="${esc(c)}" ${selected.has(c)?'checked':''}> <span>${esc(c)}</span></label>`).join('');box.querySelectorAll('input').forEach(i=>i.onchange=()=>{const current=new Set((hidden.value||'').split(',').map(x=>x.trim()).filter(Boolean));i.checked?current.add(i.value):current.delete(i.value);const ordered=COUNTRIES.filter(c=>current.has(c));hidden.value=ordered.join(', ');summary.textContent=ordered.length?ordered.join(', '):'Selecione um ou mais países'})};search.oninput=()=>render(search.value.trim());render('')}

